package org.springframework.samples.petclinic.acceptance;

import org.junit.jupiter.api.Test;
import org.springframework.test.web.servlet.MvcResult;
import tools.jackson.databind.node.ObjectNode;

class DiagTest extends AcceptanceBase {

	@Test
	void dumpRejection() throws Exception {
		ObjectNode o = structuredOwner();
		o.remove("city");
		MvcResult r = createOwner(o).andReturn();
		System.out.println("DIAG-STATUS=" + r.getResponse().getStatus());
		System.out.println("DIAG-CT=" + r.getResponse().getContentType());
		System.out.println("DIAG-BODY=" + r.getResponse().getContentAsString());
	}
}

